"""Compact, scene-scoped source controls and timed splitting."""
CSS = r'''<style>
#sceneWorkspaceHeading{margin:22px 0 12px}.phrase.active{outline:2px solid #b7a6ff!important;background:#494075!important;box-shadow:inset 5px 0 #cfbeff!important}.phrase.active:before{content:'▶ FRASE ATTIVA';display:block;font-size:10px;letter-spacing:.06em;color:#e9ddff;margin-bottom:7px}
.stage #active{padding:14px;border:1px solid #8173b0;border-radius:12px;background:#302c4a;margin-bottom:14px}.stage #active h2{font-size:18px;line-height:1.4;margin:8px 0}.providerFold{border:1px solid #454967;border-radius:10px;margin:9px 0;padding:0 12px}.providerFold>summary{padding:12px 0;cursor:pointer;font-size:13px;font-weight:700}.providerFold .shelfHead{margin:0!important;padding-top:0!important;border:0!important}.providerFold .shelfHead>h3{display:none}.providerFold .galleryBarV9{flex-wrap:wrap;gap:8px;margin:5px 0}.manualQuery{display:flex;gap:6px;width:100%;margin:6px 0}.manualQuery input{flex:1;min-width:80px;background:#181b32;color:#eee;border:1px solid #5b6084;border-radius:7px;padding:8px}.providerFold .cards{gap:8px!important}.providerFold .card .copy{padding:8px!important;font-size:11px}.providerFold .card video,.providerFold .card img,.providerFold .card iframe{max-height:155px!important;object-fit:cover}.providerFold .card{min-width:0!important}.providerFold .providerProgressV9{min-height:18px;margin:4px 0}.providerFold .portraitSocialV6>.copy{gap:5px;padding:7px!important}.providerFold .shelfHead small{display:none}
#splitSceneDialog{color:#eee;background:#22263f;border:1px solid #8b7eb9;border-radius:16px;width:min(680px,85vw);padding:22px}#splitSceneDialog::backdrop{background:#0009}#splitSceneWords{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0}#splitSceneWords button{padding:6px 8px}#splitSceneWords button.cut{background:#7464b5}#splitScenePreview{white-space:pre-wrap;line-height:1.6}.placeCoverageGroup{grid-column:1/-1;color:#e2d0a5;font-size:15px;margin:16px 0 2px}
.providerFold :is(#verticalVideos,#tiktokVideosV2,#instagramVideosV2,#stockVideos,#envatoVideosV2,#videos,#webNewsVideosV2){grid-template-columns:repeat(auto-fill,minmax(150px,1fr))!important;gap:8px!important}.providerFold .copy>b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12px;line-height:1.35}.providerFold .copy>small{display:none}.providerFold .copy>button,.providerFold .copy>a{padding:6px 8px!important;min-height:29px!important;font-size:11px!important}.providerFold .card img,.providerFold .card video{height:120px!important;max-height:120px!important}.providerFold .portraitSocialV6{align-self:start}.providerFold .copy>div{font-size:10px}
</style>'''

JS = r'''
const sourceFoldState=new Map();
function installCompactSources(){
 const chunk=activeChunkV2();if(!chunk)return;
 for(const [id,provider] of [['verticalVideos','youtube_shorts'],['videos','youtube'],['stockVideos','pexels'],['envatoVideosV2','envato'],['tiktokVideosV2','tiktok'],['instagramVideosV2','instagram'],['webNewsVideosV2','web_video'],['images','images']]){
  const box=$(id);if(!box)continue;
  const shell=box.closest('.galleryShellV9')||box;let fold=shell.closest('.providerFold');
  if(!fold){const header=providerHeaderV25(shell);if(!header)continue;fold=document.createElement('details');fold.className='providerFold';const summary=document.createElement('summary');summary.dataset.name=header.querySelector('h3')?.textContent||provider;fold.append(summary);header.before(fold);let node=header;while(node){const next=node.nextElementSibling;fold.append(node);if(node===shell)break;node=next}}
  const count=(chunk.assets||[]).filter(a=>provider==='images'?a.kind==='image':a.provider===provider&&a.kind==='video').length;
  const key=`${state.pid}:${chunk.id}:${provider}`;let saved=sourceFoldState.get(key);if(!saved)saved={open:count>0,count};else if(count>saved.count)saved.open=true;saved.count=count;sourceFoldState.set(key,saved);
  fold.ontoggle=null;fold.open=saved.open;fold.querySelector('summary').textContent=`${fold.querySelector('summary').dataset.name} · ${count} risultati`;fold.ontoggle=()=>{saved.open=fold.open};
  if(provider==='images')continue;
  let form=fold.querySelector('.manualQuery');if(!form){form=document.createElement('form');form.className='manualQuery';form.innerHTML='<input aria-label="Query manuale per questa frase" maxlength="180" placeholder="Cerca per questa frase, es. tourist police Egypt"><button type="submit">CERCA</button>';shell.before(form)}
  const g=galleryStateV9(provider),input=form.querySelector('input');input.value=g.manual||'';input.oninput=()=>{g.manual=input.value};form.querySelector('button').disabled=!!state.run||chunk.action!=='BROLL';form.onsubmit=async e=>{e.preventDefault();const query=input.value.trim();if(!query||state.run||state.active!==chunk.id)return;try{await researchBeatV2('append',[provider],{variation_round:g.round+1,query_overrides:{'*':query}})}catch(error){reportError(error)}};
 }
 const active=$('active');if(chunk.action==='BROLL'&&!$('splitSceneButton')){const button=document.createElement('button');button.id='splitSceneButton';button.textContent='✂ Dividi frase';button.title='Dividi in due scene al tempo della parola scelta';button.disabled=!!state.run;button.onclick=()=>openSplitScene(chunk.id);active.append(button)}
}
async function openSplitScene(beatId){
 try{const pid=state.pid,data=await api(`/projects/${pid}/beats/${encodeURIComponent(beatId)}/split`);let dialog=$('splitSceneDialog');if(dialog)dialog.remove();dialog=document.createElement('dialog');dialog.id='splitSceneDialog';dialog.innerHTML='<h2>Dividi la frase</h2><p>Clicca sulla prima parola della seconda scena. La clip già scelta rimane sulla prima; la seconda sarà da selezionare.</p><div id="splitSceneWords"></div><div id="splitScenePreview"></div><p id="splitSceneError" role="status"></p><div class="row"><button id="confirmSplitScene" disabled>DIVIDI E SALVA</button><button id="cancelSplitScene">ANNULLA</button></div>';document.body.append(dialog);let cut=0;data.words.forEach((word,index)=>{const b=document.createElement('button');b.textContent=word.text;b.disabled=index===0;b.onclick=()=>{cut=index;dialog.querySelectorAll('#splitSceneWords button').forEach((n,i)=>n.classList.toggle('cut',i===index));$('splitScenePreview').textContent='1 · '+data.words.slice(0,index).map(w=>w.text).join(' ')+'\n2 · '+data.words.slice(index).map(w=>w.text).join(' ');$('confirmSplitScene').disabled=false};$('splitSceneWords').append(b)});$('cancelSplitScene').onclick=()=>dialog.close();$('confirmSplitScene').onclick=async()=>{const button=$('confirmSplitScene');button.disabled=true;try{if(state.pid!==pid)throw Error('Il progetto è cambiato');const result=await api(`/projects/${pid}/beats/${encodeURIComponent(beatId)}/split`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cut,revision:data.revision})});state.active=result.beat_ids[0];await hydrate();dialog.close()}catch(error){$('splitSceneError').textContent=error.message;button.disabled=false}};dialog.showModal()}catch(error){reportError(error)}
}
const sceneDraw=draw;draw=function(){if(state.filter==='broll'&&!state.data.chunks?.some(c=>c.id===state.active&&c.action==='BROLL'))state.active=state.data.chunks?.find(c=>c.action==='BROLL')?.id||null;sceneDraw();installCompactSources()};
'''
